class Solution {
public:
    int maximumDifference(vector<int>& a) {
        int mn = a[0], ans = -1;
        for (int j = 1; j < (int)a.size(); j++) {
            if (a[j] > mn) ans = max(ans, a[j] - mn);
            mn = min(mn, a[j]);
        }
        return ans;
    }
};
