class Solution {
public:
    int maxScoreSightseeingPair(vector<int>& a) {
        int bestLeft = a[0], ans = 0;
        for (int j = 1; j < (int)a.size(); j++) {
            ans = max(ans, bestLeft + a[j] - j);
            bestLeft = max(bestLeft, a[j] + j);
        }
        return ans;
    }
};
